{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE vahdam_db.maplemonk1.vahdam_us_retail_pnl_fy27 AS ( WITH params AS (SELECT 90.0::FLOAT AS fx_inr), sku_master_raw AS ( SELECT \'USA\' AS geo, \'Walmart\' AS src, TRIM(\"Walmart Offline\",\' \t\r\n\') AS retailer_item, TRIM(\"Common SKU ID\",\' \t\r\n\') AS common_sku_id, TRIM(\"Common SKU Description\",\' \t\r\n\') AS common_sku_description, TRIM(BRAND,\' \t\r\n\') AS brand, TRIM(CATEGORY,\' \t\r\n\') AS category, TRIM(\"Sub-category\",\' \t\r\n\') AS sub_category, TRIM(\"Common Name\",\' \t\r\n\') AS common_name, TRIM(\"Master SKU\",\' \t\r\n\') AS master_sku, TRIM(\"Type-3\",\' \t\r\n\') AS type_3, TRIM(FORMAT,\' \t\r\n\') AS pack_format FROM vahdam_db.maplemonk.VAHDAM_FY27_INPUTS_PRODUCT_MAPPING WHERE NULLIF(TRIM(\"Walmart Offline\",\' \t\r\n\'),\'\') IS NOT NULL UNION ALL SELECT \'USA\', \'Target\', TRIM(\"Target \",\' \t\r\n\'), TRIM(\"Common SKU ID\",\' \t\r\n\'), TRIM(\"Common SKU Description\",\' \t\r\n\'), TRIM(BRAND,\' \t\r\n\'), TRIM(CATEGORY,\' \t\r\n\'), TRIM(\"Sub-category\",\' \t\r\n\'), TRIM(\"Common Name\",\' \t\r\n\'), TRIM(\"Master SKU\",\' \t\r\n\'), TRIM(\"Type-3\",\' \t\r\n\'), TRIM(FORMAT,\' \t\r\n\') FROM vahdam_db.maplemonk.VAHDAM_FY27_INPUTS_PRODUCT_MAPPING WHERE NULLIF(TRIM(\"Target \",\' \t\r\n\'),\'\') IS NOT NULL ), sku_master AS ( SELECT geo, src, retailer_item, common_sku_id, common_sku_description, brand, category, sub_category, common_name, master_sku, type_3, pack_format FROM sku_master_raw QUALIFY ROW_NUMBER() OVER (PARTITION BY geo, src, retailer_item ORDER BY IFF(NULLIF(common_sku_id,\'\') IS NULL,1,0), common_sku_id, common_sku_description, category, sub_category) = 1 ), cp_rates_raw AS ( SELECT \'USA\' AS geo, \'Walmart\' AS src, TRIM(\"Walmart Item #\",\' \t\r\n\') AS retailer_item, NULLIF(TRIM(\"Budget Common SKU\",\' \t\r\n\'),\'\') AS budget_sku, NULLIF(TRIM(\"Common SKU (SAP)\",\' \t\r\n\'),\'\') AS sap_sku, NULLIF(TRIM(\"Common SKU (Product Mapping)\",\' \t\r\n\'),\'\') AS pm_sku_cp, NULLIF(TRIM(\"Common SKU Desc (Product Mapping)\",\' \t\r\n\'),\'\') AS sku_description_cp, TRY_TO_NUMBER(TRIM(\"Case Pack\",\' \t\r\n\')) AS case_pack, LOWER(NULLIF(TRIM(\"Budget UOM\",\' \t\r\n\'),\'\')) AS budget_uom, NULLIF(TRIM(\"Made in USA?\",\' \t\r\n\'),\'\') AS made_in_usa, TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"ASP per Each (Vahdam to Walmart) $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6) AS asp_per_each_usd, TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"POS ASP $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6) AS pos_asp_usd, TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"Budgeted COGS / each $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6) AS cogs_per_each_usd_cp, TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"Budgeted Outbound / each $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6) AS outbound_per_each_usd_cp, TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"Budgeted 3PL + Storage / each $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6) AS three_pl_storage_per_each_usd_cp, _AIRBYTE_EMITTED_AT AS emitted_at FROM vahdam_db.maplemonk1.VAHDAM_FY27_INPUTS_WALMART_CP___BUDGET UNION ALL SELECT \'USA\', \'Target\', TRIM(\"Target TCIN\",\' \t\r\n\'), NULLIF(TRIM(\"Budget Common SKU\",\' \t\r\n\'),\'\'), NULLIF(TRIM(\"Common SKU (SAP)\",\' \t\r\n\'),\'\'), NULLIF(TRIM(\"Common SKU (Product Mapping)\",\' \t\r\n\'),\'\'), NULLIF(TRIM(\"Common SKU Desc (Product Mapping)\",\' \t\r\n\'),\'\'), TRY_TO_NUMBER(TRIM(\"Case Pack\",\' \t\r\n\')), \'each\', NULLIF(TRIM(\"Made in USA?\",\' \t\r\n\'),\'\'), TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"ASP (Vahdam to Target) $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6), TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"POS ASP $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6), TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"Budgeted COGS / each $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6), TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"Budgeted Outbound / each $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6), TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"Budgeted 3PL + Storage / each $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6), _AIRBYTE_EMITTED_AT FROM vahdam_db.maplemonk1.VAHDAM_FY27_INPUTS_TARGET_CP___BUDGET ), cp_rates AS ( SELECT geo, src, retailer_item, budget_sku, sap_sku, pm_sku_cp, sku_description_cp, case_pack, budget_uom, made_in_usa, asp_per_each_usd, pos_asp_usd, cogs_per_each_usd_cp, outbound_per_each_usd_cp, three_pl_storage_per_each_usd_cp FROM cp_rates_raw WHERE NULLIF(retailer_item,\'\') IS NOT NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY geo, src, retailer_item ORDER BY IFF(asp_per_each_usd IS NULL,1,0), IFF(cogs_per_each_usd_cp IS NULL,1,0), emitted_at DESC NULLS LAST, budget_sku) = 1 ), budget_uom_map AS ( SELECT src, budget_sku, MAX(case_pack) AS case_pack, MAX(budget_uom) AS budget_uom FROM cp_rates_raw WHERE budget_sku IS NOT NULL GROUP BY 1,2 ), walmart_pos_rows AS ( SELECT TRY_TO_DATE(SPLIT_PART(BUSINESS_DATE,\' \',1),\'YYYY-MM-DD\') AS day, TRIM(WALMART_ITEM_NUMBER,\' \t\r\n\') AS retailer_item, TRIM(STORE_NUMBER,\' \t\r\n\') AS store_number, ITEM_NAME AS item_name, TRY_TO_DECIMAL(REGEXP_REPLACE(POS_QUANTITY_THIS_YEAR::STRING,\'[^0-9.\-]\',\'\'),30,4) AS pos_units, TRY_TO_DECIMAL(REGEXP_REPLACE(POS_SALES_THIS_YEAR::STRING ,\'[^0-9.\-]\',\'\'),30,4) AS pos_retail_usd FROM vahdam_db.maplemonk1.WALMART_SALES_DATA_WALMART_SALES_DATA_RAW WHERE TRY_TO_DATE(SPLIT_PART(BUSINESS_DATE,\' \',1),\'YYYY-MM-DD\') IS NOT NULL AND NULLIF(TRIM(WALMART_ITEM_NUMBER,\' \t\r\n\'),\'\') IS NOT NULL QUALIFY ROW_NUMBER() OVER ( PARTITION BY TRY_TO_DATE(SPLIT_PART(BUSINESS_DATE,\' \',1),\'YYYY-MM-DD\'), TRIM(STORE_NUMBER,\' \t\r\n\'), TRIM(WALMART_ITEM_NUMBER,\' \t\r\n\') ORDER BY _AB_SOURCE_FILE_LAST_MODIFIED DESC NULLS LAST, _AB_SOURCE_FILE_URL DESC NULLS LAST, _AIRBYTE_EMITTED_AT DESC NULLS LAST) = 1 ), pos_walmart AS ( SELECT day, retailer_item, MAX(item_name) AS retailer_item_name, SUM(pos_units) AS pos_units, SUM(pos_retail_usd) AS pos_retail_usd, COUNT(DISTINCT CASE WHEN pos_units > 0 THEN store_number END) AS selling_locations FROM walmart_pos_rows GROUP BY 1,2 ), target_pos_src AS ( SELECT COALESCE(TRY_TO_DATE(SPLIT_PART(\"DATE\",\' \',1),\'DD-MM-YYYY\'), TRY_TO_DATE(SPLIT_PART(\"DATE\",\' \',1),\'YYYY-MM-DD\')) AS day, TRIM(\"TCIN\",\' \t\r\n\') AS retailer_item, TRIM(\"LOCATION ID\",\' \t\r\n\') AS location_id, TRIM(\"ITEM DESCRIPTION\",\' \t\r\n\') AS item_name, TRIM(\"CHANNEL - FULFILLED\",\' \t\r\n\') AS channel_fulfilled, TRIM(\"FULFILLMENT METHOD - FULFILLED\",\' \t\r\n\') AS fulfillment_method, TRY_TO_DECIMAL(REPLACE(\"SALES U\",\',\',\'\'),30,4) AS pos_units, TRY_TO_DECIMAL(REPLACE(REPLACE(\"SALES $\",\'$\',\'\'),\',\',\'\'),30,4) AS pos_retail_usd, _AB_SOURCE_FILE_LAST_MODIFIED AS file_modified, _AB_SOURCE_FILE_URL AS file_url, _AIRBYTE_EMITTED_AT AS emitted_at FROM vahdam_db.maplemonk1.TARGET_SALES_TARGET_SALES ), target_pos_rows AS ( SELECT day, retailer_item, location_id, item_name, pos_units, pos_retail_usd FROM target_pos_src WHERE day IS NOT NULL AND NULLIF(retailer_item,\'\') IS NOT NULL QUALIFY DENSE_RANK() OVER (PARTITION BY day, location_id, retailer_item ORDER BY file_modified DESC NULLS LAST, file_url DESC NULLS LAST) = 1 AND ROW_NUMBER() OVER (PARTITION BY day, location_id, retailer_item, channel_fulfilled, fulfillment_method, file_modified, file_url ORDER BY emitted_at DESC NULLS LAST) = 1 ), pos_target AS ( SELECT day, retailer_item, MAX(item_name) AS retailer_item_name, SUM(pos_units) AS pos_units, SUM(pos_retail_usd) AS pos_retail_usd, COUNT(DISTINCT CASE WHEN pos_units > 0 THEN location_id END) AS selling_locations FROM target_pos_rows GROUP BY 1,2 ), pos_all AS ( SELECT \'USA\' AS geo, \'Walmart\' AS src, day, retailer_item, retailer_item_name, pos_units, pos_retail_usd, selling_locations FROM pos_walmart UNION ALL SELECT \'USA\', \'Target\', day, retailer_item, retailer_item_name, pos_units, pos_retail_usd, selling_locations FROM pos_target ), actuals AS ( SELECT p.day, p.geo, p.src, p.retailer_item, p.retailer_item_name, CASE WHEN p.src = \'Target\' THEN \'Target\' WHEN COALESCE(m.common_sku_id, c.sap_sku) IN (\'TB024003369-GT\',\'TB024003368-BT\',\'LF060003372-CT\',\'LF060003371-BT\') THEN \'Private Label\' ELSE \'Walmart\' END AS channel, COALESCE(m.common_sku_id, c.pm_sku_cp, c.sap_sku, c.budget_sku) AS common_sku_id, COALESCE(m.common_sku_description, c.sku_description_cp) AS common_sku_description, c.budget_sku, c.sap_sku, c.pm_sku_cp AS pm_sku, m.brand, m.category, m.sub_category, m.common_name, m.master_sku, m.type_3, m.pack_format, COALESCE(c.case_pack,1) AS case_pack, c.budget_uom, c.made_in_usa, c.asp_per_each_usd, c.pos_asp_usd, c.cogs_per_each_usd_cp, c.outbound_per_each_usd_cp, c.three_pl_storage_per_each_usd_cp, DATE_TRUNC(\'MONTH\', p.day) AS month_start, p.pos_units AS qty_actual_eaches, p.pos_retail_usd AS pos_retail_sales_usd, p.selling_locations, p.pos_units * c.asp_per_each_usd AS net_sales_actual_usd, CASE WHEN m.retailer_item IS NULL THEN \'UNMAPPED\' WHEN c.retailer_item IS NULL THEN \'MAPPED_NO_RATES\' WHEN c.asp_per_each_usd IS NULL THEN \'MAPPED_NO_ASP\' ELSE \'OK\' END AS sku_setup_status FROM pos_all p LEFT JOIN sku_master m ON m.retailer_item = p.retailer_item AND m.geo = p.geo AND m.src = p.src LEFT JOIN cp_rates c ON c.retailer_item = p.retailer_item AND c.geo = p.geo AND c.src = p.src ), budget_raw AS ( SELECT TRIM(b.\"Common SKU\",\' \t\r\n\') AS budget_sku, b.\"Platform\" AS channel, UPPER(b.\"Geography\") AS geo, b.\"MONTH_DT\" AS month_start, COALESCE(d.case_pack,1) AS case_pack, CASE WHEN LOWER(COALESCE(d.budget_uom,\'each\')) = \'case\' AND COALESCE(d.case_pack,1) > 1 THEN d.case_pack ELSE 1 END AS uom_factor, SUM(b.\"Qty\") AS qty_budget_uom, SUM(b.\"Net Sales\") AS net_sales_budget_inr, SUM(b.\"COGS\") AS cogs_budget_inr, SUM(b.\"TP Value\") AS tp_budget_inr, SUM(b.\"Add Tariff\") AS tariff_budget_inr, SUM(b.\"Commission\") AS commission_budget_inr, SUM(b.\"Outbound\") AS outbound_budget_inr, SUM(b.\"3PL + Storage\") AS three_pl_storage_budget_inr, SUM(b.\"Last mile\") AS last_mile_budget_inr, SUM(b.\"Payment Commission\") AS payment_commission_budget_inr, SUM(b.\"Performance Marketing\") AS pm_budget_inr, SUM(b.\"Cost of Offline Sales\") AS coos_budget_inr FROM vahdam_db.maplemonk1.OFFLINE_BUDGET_FY27 b LEFT JOIN budget_uom_map d ON d.budget_sku = TRIM(b.\"Common SKU\",\' \t\r\n\') AND d.src = CASE WHEN b.\"Platform\" = \'Target\' THEN \'Target\' ELSE \'Walmart\' END WHERE b.\"Platform\" IN (\'Walmart\',\'Target\',\'Private Label\') AND UPPER(b.\"Geography\") = \'USA\' AND NULLIF(TRIM(b.\"Common SKU\",\' \t\r\n\'),\'\') IS NOT NULL GROUP BY 1,2,3,4,5,6 ), budget_rates AS ( SELECT budget_sku, channel, geo, month_start, case_pack, qty_budget_uom * uom_factor AS qty_budget_eaches, net_sales_budget_inr, cogs_budget_inr, tp_budget_inr, tariff_budget_inr, commission_budget_inr, outbound_budget_inr, three_pl_storage_budget_inr, last_mile_budget_inr, payment_commission_budget_inr, pm_budget_inr, coos_budget_inr, DIV0(cogs_budget_inr , qty_budget_uom * uom_factor) AS cogs_per_each_inr, DIV0(tp_budget_inr , qty_budget_uom * uom_factor) AS tp_per_each_inr, DIV0(tariff_budget_inr , qty_budget_uom * uom_factor) AS tariff_per_each_inr, DIV0(outbound_budget_inr , qty_budget_uom * uom_factor) AS outbound_per_each_inr, DIV0(three_pl_storage_budget_inr , qty_budget_uom * uom_factor) AS three_pl_storage_per_each_inr, DIV0(last_mile_budget_inr , qty_budget_uom * uom_factor) AS last_mile_per_each_inr, DIV0(commission_budget_inr , net_sales_budget_inr) AS commission_pct_budget, DIV0(payment_commission_budget_inr , net_sales_budget_inr) AS payment_commission_pct_budget FROM budget_raw ), budget_rates_sku AS ( SELECT budget_sku, channel, geo, AVG(cogs_per_each_inr) AS cogs_per_each_inr_avg, AVG(tp_per_each_inr) AS tp_per_each_inr_avg, AVG(tariff_per_each_inr) AS tariff_per_each_inr_avg, AVG(outbound_per_each_inr) AS outbound_per_each_inr_avg, AVG(three_pl_storage_per_each_inr) AS three_pl_storage_per_each_inr_avg, AVG(last_mile_per_each_inr) AS last_mile_per_each_inr_avg, AVG(commission_pct_budget) AS commission_pct_avg, AVG(payment_commission_pct_budget) AS payment_commission_pct_avg FROM budget_rates GROUP BY 1,2,3 ), commission_src AS ( SELECT CASE WHEN REPLACE(TRIM(\"CHANNEL\",\' \t\r\n\'),\' \',\'\') = \'PrivateLabel\' THEN \'Private Label\' ELSE TRIM(\"CHANNEL\",\' \t\r\n\') END AS channel, TRY_TO_DECIMAL(REPLACE(TRIM(\"Budget Commission %\",\' \t\r\n\'),\'%\',\'\'),30,6)/100 AS commission_pct_driver, _AIRBYTE_EMITTED_AT AS emitted_at FROM vahdam_db.maplemonk1.VAHDAM_FY27_INPUTS_OFFLINE_COMMISSION ), commission_driver AS ( SELECT channel, commission_pct_driver FROM commission_src WHERE NULLIF(channel,\'\') IS NOT NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY channel ORDER BY IFF(commission_pct_driver IS NULL,1,0), emitted_at DESC NULLS LAST) = 1 ), coos_src AS ( SELECT CASE WHEN REPLACE(TRIM(\"CHANNEL\",\' \t\r\n\'),\' \',\'\') = \'PrivateLabel\' THEN \'Private Label\' ELSE TRIM(\"CHANNEL\",\' \t\r\n\') END AS channel, TRIM(\"CHARGE\",\' \t\r\n\') AS charge, TRY_TO_DECIMAL(REPLACE(TRIM(\"Budget%\",\' \t\r\n\'),\'%\',\'\'),30,6)/100 AS coos_pct, _AIRBYTE_EMITTED_AT AS emitted_at FROM vahdam_db.maplemonk1.VAHDAM_FY27_INPUTS_OFFLINE_COOS WHERE UPPER(TRIM(\"GEO\",\' \t\r\n\')) = \'USA\' ), coos_driver AS ( SELECT channel, SUM(coos_pct) AS coos_pct_driver FROM (SELECT channel, coos_pct FROM coos_src WHERE NULLIF(channel,\'\') IS NOT NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY channel, charge ORDER BY emitted_at DESC NULLS LAST) = 1) GROUP BY 1 ), other_coos_src AS ( SELECT TRIM(\"CHARGE\",\' \t\r\n\') AS charge, \"April-2026\",\"May-2026\",\"June-2026\",\"July-2026\",\"August-2026\", \"September-2026\",\"October-2026\",\"November-2026\",\"December-2026\", \"January-2027\",\"February-2027\",\"March-2027\" FROM vahdam_db.maplemonk1.VAHDAM_FY27_INPUTS_OFFLINE_OTHER_COOS WHERE COALESCE(NULLIF(UPPER(TRIM(\"GEO\",\' \t\r\n\')),\'\'),\'USA\') = \'USA\' AND NULLIF(TRIM(\"CHARGE\",\' \t\r\n\'),\'\') IS NOT NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY TRIM(\"CHARGE\",\' \t\r\n\') ORDER BY _AIRBYTE_EMITTED_AT DESC NULLS LAST) = 1 ), other_coos_raw AS ( SELECT charge, mth, TRY_TO_DECIMAL(REPLACE(val,\',\',\'\'),30,4) AS amt_inr FROM other_coos_src UNPIVOT INCLUDE NULLS (val FOR mth IN (\"April-2026\",\"May-2026\",\"June-2026\",\"July-2026\",\"August-2026\", \"September-2026\",\"October-2026\",\"November-2026\",\"December-2026\", \"January-2027\",\"February-2027\",\"March-2027\")) ), other_coos_month AS ( SELECT charge, TO_DATE(\'01-\'||REPLACE(mth,\'-\',\' -\'), \'DD-MMMM -YYYY\') AS month_start, amt_inr FROM other_coos_raw ), other_coos_filled AS ( SELECT charge, month_start, amt_inr AS amt_reported, COALESCE( amt_inr, AVG(amt_inr) OVER (PARTITION BY charge ORDER BY month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) ) AS amt_used_inr FROM other_coos_month ), other_coos_total AS ( SELECT month_start, SUM(amt_used_inr) AS other_coos_total_inr FROM other_coos_filled GROUP BY 1 ), other_coos_daily AS ( SELECT month_start, other_coos_total_inr, other_coos_total_inr / DAY(LAST_DAY(month_start)) AS other_coos_per_day_inr FROM other_coos_total ), pm_walmart AS ( SELECT DATE_TRUNC(\'MONTH\', d) AS month_start, SUM(usd) AS spend_usd FROM (SELECT \"c_DATE\" AS d, COALESCE(ADSPEND, TRY_TO_DOUBLE(ADSPEND_ST)) AS usd FROM DATON.RAW.WALMART_CONNECT_US_1P_ADGROUPSNAPSHOTREPORT WHERE \"c_DATE\" IS NOT NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY \"c_DATE\", COALESCE(CAMPAIGNID_ST, TO_VARCHAR(CAMPAIGNID::NUMBER(38,0))), COALESCE(ADGROUPID_ST, TO_VARCHAR(ADGROUPID::NUMBER(38,0))) ORDER BY DATON_BATCH_RUNTIME DESC NULLS LAST, DATON_BATCH_ID DESC NULLS LAST) = 1) GROUP BY 1 ), pm_target AS ( SELECT DATE_TRUNC(\'MONTH\', d) AS month_start, SUM(usd) AS spend_usd FROM (SELECT d, usd FROM (SELECT COALESCE(TRY_TO_DATE(SPLIT_PART(\"Event Date\",\' \',1),\'DD-MM-YYYY\'), TRY_TO_DATE(SPLIT_PART(\"Event Date\",\' \',1),\'YYYY-MM-DD\')) AS d, TRY_TO_DOUBLE(REPLACE(REPLACE(\"Actualized Vendor Spend\",\'$\',\'\'),\',\',\'\')) AS usd, \"Account Name\" AS acct, \"Campaign Name\" AS camp, \"Media Name\" AS media, \"Platform Name\" AS plat, _AB_SOURCE_FILE_LAST_MODIFIED AS file_modified, _AB_SOURCE_FILE_URL AS file_url, _AIRBYTE_EMITTED_AT AS emitted_at FROM vahdam_db.maplemonk1.TARGET_ADS_DAY_TARGET_ADS_REPORT) WHERE d IS NOT NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY d, acct, camp, media, plat ORDER BY file_modified DESC NULLS LAST, file_url DESC NULLS LAST, emitted_at DESC NULLS LAST) = 1) GROUP BY 1 ), cashback_ibotta AS ( SELECT DATE_TRUNC(\'MONTH\', d) AS month_start, SUM(usd) AS spend_usd FROM (SELECT d, usd FROM (SELECT COALESCE(TRY_TO_DATE(SPLIT_PART(\"DATE\",\' \',1),\'DD-MM-YYYY\'), TRY_TO_DATE(SPLIT_PART(\"DATE\",\' \',1),\'YYYY-MM-DD\')) AS d, TRIM(\"Offer ID\"::STRING,\' \t\r\n\') AS offer_id, COALESCE(TRY_TO_DOUBLE(REPLACE(REPLACE(_AB_ADDITIONAL_PROPERTIES:\"Total_daily_spend\"::STRING,\'$\',\'\'),\',\',\'\')), TRY_TO_DOUBLE(REPLACE(REPLACE(\"Total Spend ($)\",\'$\',\'\'),\',\',\'\'))) AS usd, _AB_SOURCE_FILE_LAST_MODIFIED AS file_modified, _AB_SOURCE_FILE_URL AS file_url, _AIRBYTE_EMITTED_AT AS emitted_at FROM vahdam_db.maplemonk1.TARGET_IBOTTA_REPORT_TARGET_IBOTTA_REPORT) WHERE d IS NOT NULL AND usd IS NOT NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY d, offer_id ORDER BY file_modified DESC NULLS LAST, emitted_at DESC NULLS LAST, file_url DESC NULLS LAST) = 1) GROUP BY 1 ), aisle_src AS ( SELECT COALESCE(TRY_TO_DATE(SPLIT_PART(\"DATE\",\' \',1),\'DD-MM-YYYY\'), TRY_TO_DATE(SPLIT_PART(\"DATE\",\' \',1),\'YYYY-MM-DD\')) AS day, (CASE WHEN \"Fees ($)\" LIKE \'(%\' THEN -1 ELSE 1 END * TRY_TO_DOUBLE(REPLACE(REPLACE(REPLACE(REPLACE(\"Fees ($)\" ,\'(\',\'\'),\')\',\'\'),\'$\',\'\'),\',\',\'\'))) AS fees, (CASE WHEN \"Payout ($)\" LIKE \'(%\' THEN -1 ELSE 1 END * TRY_TO_DOUBLE(REPLACE(REPLACE(REPLACE(REPLACE(\"Payout ($)\",\'(\',\'\'),\')\',\'\'),\'$\',\'\'),\',\',\'\'))) AS payout, ROW_NUMBER() OVER (PARTITION BY COALESCE(TRY_TO_DATE(SPLIT_PART(\"DATE\",\' \',1),\'DD-MM-YYYY\'), TRY_TO_DATE(SPLIT_PART(\"DATE\",\' \',1),\'YYYY-MM-DD\')), \"CAMPAIGN\" ORDER BY \"_AB_SOURCE_FILE_LAST_MODIFIED\" DESC NULLS LAST, \"_AB_SOURCE_FILE_URL\" DESC NULLS LAST, \"_AIRBYTE_EMITTED_AT\" DESC NULLS LAST) rn FROM vahdam_db.maplemonk1.TARGET_AISLE_TARGET_AISLE_REPORT ), cashback_aisle AS ( SELECT DATE_TRUNC(\'MONTH\',day) AS month_start, SUM(COALESCE(fees,0)+COALESCE(payout,0)) AS spend_usd FROM aisle_src WHERE rn = 1 AND day IS NOT NULL GROUP BY 1 ), spend_by_channel_month AS ( SELECT \'Walmart\' AS channel, month_start, spend_usd AS pm_spend_usd, 0 AS cashback_spend_usd FROM pm_walmart UNION ALL SELECT \'Target\', COALESCE(t.month_start,i.month_start,a.month_start), COALESCE(t.spend_usd,0), COALESCE(i.spend_usd,0) + COALESCE(a.spend_usd,0) FROM pm_target t FULL JOIN cashback_ibotta i ON i.month_start = t.month_start FULL JOIN cashback_aisle a ON a.month_start = COALESCE(t.month_start,i.month_start) ), sales_channel_month AS ( SELECT channel, geo, month_start, SUM(net_sales_actual_usd) AS ch_sales_usd FROM actuals GROUP BY 1,2,3 ), sales_all_month AS ( SELECT month_start, SUM(net_sales_actual_usd) AS all_sales_usd FROM actuals GROUP BY 1 ), sales_all_day AS ( SELECT day, SUM(net_sales_actual_usd) AS all_sales_usd_day FROM actuals GROUP BY 1 ), joined AS ( SELECT a.day, a.month_start, a.channel, a.geo, a.retailer_item, a.retailer_item_name, a.common_sku_id, a.common_sku_description, a.budget_sku, a.sap_sku, a.pm_sku, a.sku_setup_status, a.case_pack, a.budget_uom, a.made_in_usa, a.selling_locations, a.brand, a.category, a.sub_category, a.common_name, a.master_sku, a.type_3, a.pack_format, p.fx_inr, a.qty_actual_eaches, a.asp_per_each_usd, a.pos_asp_usd, a.pos_retail_sales_usd, a.net_sales_actual_usd, COALESCE(a.cogs_per_each_usd_cp * p.fx_inr, br.cogs_per_each_inr, brs.cogs_per_each_inr_avg) AS cogs_per_each_inr, COALESCE(br.tp_per_each_inr , brs.tp_per_each_inr_avg) AS tp_per_each_inr, COALESCE(br.tariff_per_each_inr , brs.tariff_per_each_inr_avg) AS tariff_per_each_inr, COALESCE(a.outbound_per_each_usd_cp * p.fx_inr, br.outbound_per_each_inr, brs.outbound_per_each_inr_avg) AS outbound_per_each_inr, COALESCE(a.three_pl_storage_per_each_usd_cp * p.fx_inr, br.three_pl_storage_per_each_inr, brs.three_pl_storage_per_each_inr_avg) AS three_pl_storage_per_each_inr, COALESCE(br.last_mile_per_each_inr , brs.last_mile_per_each_inr_avg) AS last_mile_per_each_inr, COALESCE(cd.commission_pct_driver, br.commission_pct_budget, brs.commission_pct_avg) AS commission_pct, COALESCE(br.payment_commission_pct_budget, brs.payment_commission_pct_avg) AS payment_commission_pct, COALESCE(cod.coos_pct_driver, 0) AS coos_pct, DIV0(a.net_sales_actual_usd, scm.ch_sales_usd) AS share_of_channel_month, DIV0(a.net_sales_actual_usd, sam.all_sales_usd) AS share_of_all_month, COALESCE(sp.pm_spend_usd,0) * DIV0(a.net_sales_actual_usd, scm.ch_sales_usd) AS pm_spend_actual_usd, COALESCE(sp.cashback_spend_usd,0) * DIV0(a.net_sales_actual_usd, scm.ch_sales_usd) AS cashback_spend_actual_usd, DIV0(a.net_sales_actual_usd, sad.all_sales_usd_day) AS share_of_all_day, COALESCE(ocd.other_coos_per_day_inr,0) * DIV0(a.net_sales_actual_usd, sad.all_sales_usd_day) AS other_coos_inr, CASE WHEN br.budget_sku IS NOT NULL THEN \'N\' WHEN brs.budget_sku IS NOT NULL THEN \'Y\' ELSE \'NO_BUDGET\' END AS cost_rate_carried_forward, CASE WHEN a.cogs_per_each_usd_cp IS NOT NULL THEN \'CP_INPUT_TABLE\' WHEN br.cogs_per_each_inr IS NOT NULL THEN \'BUDGET_DERIVED\' WHEN brs.cogs_per_each_inr_avg IS NOT NULL THEN \'BUDGET_SKU_AVG\' ELSE \'NONE\' END AS cogs_rate_source, CASE WHEN a.outbound_per_each_usd_cp IS NOT NULL THEN \'CP_INPUT_TABLE\' WHEN br.outbound_per_each_inr IS NOT NULL THEN \'BUDGET_DERIVED\' WHEN brs.outbound_per_each_inr_avg IS NOT NULL THEN \'BUDGET_SKU_AVG\' ELSE \'NONE\' END AS outbound_rate_source, CASE WHEN a.three_pl_storage_per_each_usd_cp IS NOT NULL THEN \'CP_INPUT_TABLE\' WHEN br.three_pl_storage_per_each_inr IS NOT NULL THEN \'BUDGET_DERIVED\' WHEN brs.three_pl_storage_per_each_inr_avg IS NOT NULL THEN \'BUDGET_SKU_AVG\' ELSE \'NONE\' END AS three_pl_storage_rate_source, DAY(LAST_DAY(a.month_start)) AS days_in_month, COUNT(*) OVER (PARTITION BY a.day, a.channel, a.geo, a.budget_sku) AS budget_share_n, br.qty_budget_eaches / DAY(LAST_DAY(a.month_start)) AS qty_budget_eaches_day, br.net_sales_budget_inr / DAY(LAST_DAY(a.month_start)) AS net_sales_budget_inr_day, br.cogs_budget_inr / DAY(LAST_DAY(a.month_start)) AS cogs_budget_inr_day, br.tp_budget_inr / DAY(LAST_DAY(a.month_start)) AS tp_budget_inr_day, br.tariff_budget_inr / DAY(LAST_DAY(a.month_start)) AS tariff_budget_inr_day, br.commission_budget_inr / DAY(LAST_DAY(a.month_start)) AS commission_budget_inr_day, br.outbound_budget_inr / DAY(LAST_DAY(a.month_start)) AS outbound_budget_inr_day, br.three_pl_storage_budget_inr / DAY(LAST_DAY(a.month_start)) AS three_pl_storage_budget_inr_day, br.last_mile_budget_inr / DAY(LAST_DAY(a.month_start)) AS last_mile_budget_inr_day, br.payment_commission_budget_inr / DAY(LAST_DAY(a.month_start)) AS payment_commission_budget_inr_day, br.pm_budget_inr / DAY(LAST_DAY(a.month_start)) AS pm_budget_inr_day, br.coos_budget_inr / DAY(LAST_DAY(a.month_start)) AS coos_budget_inr_day, br.net_sales_budget_inr AS net_sales_budget_month_inr, br.qty_budget_eaches AS qty_budget_eaches_month FROM actuals a CROSS JOIN params p LEFT JOIN budget_rates br ON br.budget_sku = a.budget_sku AND br.channel = a.channel AND br.geo = a.geo AND br.month_start = a.month_start LEFT JOIN budget_rates_sku brs ON brs.budget_sku = a.budget_sku AND brs.channel = a.channel AND brs.geo = a.geo LEFT JOIN commission_driver cd ON cd.channel = a.channel LEFT JOIN coos_driver cod ON cod.channel = a.channel LEFT JOIN sales_channel_month scm ON scm.channel = a.channel AND scm.geo = a.geo AND scm.month_start = a.month_start LEFT JOIN sales_all_month sam ON sam.month_start = a.month_start LEFT JOIN spend_by_channel_month sp ON sp.channel = a.channel AND sp.month_start = a.month_start LEFT JOIN sales_all_day sad ON sad.day = a.day LEFT JOIN other_coos_daily ocd ON ocd.month_start = a.month_start ), joined_budget AS ( SELECT j.*, qty_budget_eaches_day / budget_share_n AS qty_budget_eaches, net_sales_budget_inr_day / budget_share_n AS net_sales_budget_inr, cogs_budget_inr_day / budget_share_n AS cogs_budget_inr, tp_budget_inr_day / budget_share_n AS tp_budget_inr, tariff_budget_inr_day / budget_share_n AS tariff_budget_inr, commission_budget_inr_day / budget_share_n AS commission_budget_inr, outbound_budget_inr_day / budget_share_n AS outbound_budget_inr, three_pl_storage_budget_inr_day / budget_share_n AS three_pl_storage_budget_inr, last_mile_budget_inr_day / budget_share_n AS last_mile_budget_inr, payment_commission_budget_inr_day / budget_share_n AS payment_commission_budget_inr, pm_budget_inr_day / budget_share_n AS pm_budget_inr, coos_budget_inr_day / budget_share_n AS coos_budget_inr FROM joined j ) SELECT day, month_start, CASE WHEN day >= \'2026-04-01\' AND day <= \'2027-03-31\' THEN \'FY27\' WHEN day >= \'2025-04-01\' AND day <= \'2026-03-31\' THEN \'FY26\' ELSE \'OTHER\' END AS fiscal_year, channel, geo, retailer_item, retailer_item_name, common_sku_id, common_sku_description, budget_sku, sap_sku, pm_sku, brand, category, sub_category, common_name, master_sku, type_3, pack_format, case_pack, budget_uom, made_in_usa, fx_inr, selling_locations, qty_actual_eaches, asp_per_each_usd, pos_asp_usd, pos_retail_sales_usd, net_sales_actual_usd, net_sales_actual_usd * fx_inr AS net_sales_actual_inr, qty_actual_eaches * cogs_per_each_inr / fx_inr AS cogs_actual_usd, qty_actual_eaches * tp_per_each_inr / fx_inr AS transfer_price_actual_usd, qty_actual_eaches * tariff_per_each_inr / fx_inr AS tariff_actual_usd, net_sales_actual_usd * COALESCE(commission_pct,0) AS commission_actual_usd, qty_actual_eaches * outbound_per_each_inr / fx_inr AS outbound_actual_usd, qty_actual_eaches * three_pl_storage_per_each_inr / fx_inr AS three_pl_storage_actual_usd, qty_actual_eaches * last_mile_per_each_inr / fx_inr AS last_mile_actual_usd, net_sales_actual_usd * COALESCE(payment_commission_pct,0) AS payment_commission_actual_usd, net_sales_actual_usd - COALESCE(qty_actual_eaches * cogs_per_each_inr / fx_inr, 0) - COALESCE(qty_actual_eaches * tariff_per_each_inr / fx_inr, 0) - COALESCE(net_sales_actual_usd * commission_pct, 0) - COALESCE(qty_actual_eaches * outbound_per_each_inr / fx_inr, 0) - COALESCE(qty_actual_eaches * three_pl_storage_per_each_inr / fx_inr, 0) - COALESCE(qty_actual_eaches * last_mile_per_each_inr / fx_inr, 0) - COALESCE(net_sales_actual_usd * payment_commission_pct, 0) AS cm1_actual_usd, pm_spend_actual_usd, cashback_spend_actual_usd, net_sales_actual_usd * coos_pct AS coos_channel_actual_usd, other_coos_inr / fx_inr AS other_coos_actual_usd, net_sales_actual_usd * coos_pct + other_coos_inr / fx_inr AS coos_total_actual_usd, net_sales_actual_usd - COALESCE(qty_actual_eaches * cogs_per_each_inr / fx_inr, 0) - COALESCE(qty_actual_eaches * tariff_per_each_inr / fx_inr, 0) - COALESCE(net_sales_actual_usd * commission_pct, 0) - COALESCE(qty_actual_eaches * outbound_per_each_inr / fx_inr, 0) - COALESCE(qty_actual_eaches * three_pl_storage_per_each_inr / fx_inr, 0) - COALESCE(qty_actual_eaches * last_mile_per_each_inr / fx_inr, 0) - COALESCE(net_sales_actual_usd * payment_commission_pct, 0) - COALESCE(pm_spend_actual_usd, 0) - COALESCE(cashback_spend_actual_usd, 0) - COALESCE(net_sales_actual_usd * coos_pct, 0) - COALESCE(other_coos_inr / fx_inr, 0) AS cm2_actual_usd, qty_actual_eaches * cogs_per_each_inr AS cogs_actual_inr, qty_actual_eaches * tp_per_each_inr AS transfer_price_actual_inr, qty_actual_eaches * tariff_per_each_inr AS tariff_actual_inr, net_sales_actual_usd * COALESCE(commission_pct,0) * fx_inr AS commission_actual_inr, qty_actual_eaches * outbound_per_each_inr AS outbound_actual_inr, qty_actual_eaches * three_pl_storage_per_each_inr AS three_pl_storage_actual_inr, qty_actual_eaches * last_mile_per_each_inr AS last_mile_actual_inr, net_sales_actual_usd * COALESCE(payment_commission_pct,0) * fx_inr AS payment_commission_actual_inr, ( net_sales_actual_usd - COALESCE(qty_actual_eaches * cogs_per_each_inr / fx_inr, 0) - COALESCE(qty_actual_eaches * tariff_per_each_inr / fx_inr, 0) - COALESCE(net_sales_actual_usd * commission_pct, 0) - COALESCE(qty_actual_eaches * outbound_per_each_inr / fx_inr, 0) - COALESCE(qty_actual_eaches * three_pl_storage_per_each_inr / fx_inr, 0) - COALESCE(qty_actual_eaches * last_mile_per_each_inr / fx_inr, 0) - COALESCE(net_sales_actual_usd * payment_commission_pct, 0) ) * fx_inr AS cm1_actual_inr, pm_spend_actual_usd * fx_inr AS pm_spend_actual_inr, cashback_spend_actual_usd * fx_inr AS cashback_spend_actual_inr, net_sales_actual_usd * coos_pct * fx_inr AS coos_channel_actual_inr, other_coos_inr AS other_coos_actual_inr, ( net_sales_actual_usd - COALESCE(qty_actual_eaches * cogs_per_each_inr / fx_inr, 0) - COALESCE(qty_actual_eaches * tariff_per_each_inr / fx_inr, 0) - COALESCE(net_sales_actual_usd * commission_pct, 0) - COALESCE(qty_actual_eaches * outbound_per_each_inr / fx_inr, 0) - COALESCE(qty_actual_eaches * three_pl_storage_per_each_inr / fx_inr, 0) - COALESCE(qty_actual_eaches * last_mile_per_each_inr / fx_inr, 0) - COALESCE(net_sales_actual_usd * payment_commission_pct, 0) - COALESCE(pm_spend_actual_usd, 0) - COALESCE(cashback_spend_actual_usd, 0) - COALESCE(net_sales_actual_usd * coos_pct, 0) ) * fx_inr - COALESCE(other_coos_inr,0) AS cm2_actual_inr, cogs_per_each_inr, tp_per_each_inr, tariff_per_each_inr, outbound_per_each_inr, three_pl_storage_per_each_inr, last_mile_per_each_inr, commission_pct, payment_commission_pct, coos_pct, share_of_channel_month, share_of_all_month, share_of_all_day, days_in_month, qty_budget_eaches, net_sales_budget_inr, cogs_budget_inr, tp_budget_inr, tariff_budget_inr, commission_budget_inr, outbound_budget_inr, three_pl_storage_budget_inr, last_mile_budget_inr, payment_commission_budget_inr, ( COALESCE(net_sales_budget_inr,0) - COALESCE(cogs_budget_inr,0) - COALESCE(tariff_budget_inr,0) - COALESCE(commission_budget_inr,0) - COALESCE(outbound_budget_inr,0) - COALESCE(three_pl_storage_budget_inr,0) - COALESCE(last_mile_budget_inr,0) - COALESCE(payment_commission_budget_inr,0) ) AS cm1_budget_inr, pm_budget_inr, coos_budget_inr, ( COALESCE(net_sales_budget_inr,0) - COALESCE(cogs_budget_inr,0) - COALESCE(tariff_budget_inr,0) - COALESCE(commission_budget_inr,0) - COALESCE(outbound_budget_inr,0) - COALESCE(three_pl_storage_budget_inr,0) - COALESCE(last_mile_budget_inr,0) - COALESCE(payment_commission_budget_inr,0) - COALESCE(pm_budget_inr,0) - COALESCE(coos_budget_inr,0) ) AS cm2_budget_inr, net_sales_budget_month_inr, qty_budget_eaches_month, sku_setup_status, cost_rate_carried_forward, cogs_rate_source, outbound_rate_source, three_pl_storage_rate_source, CASE WHEN cogs_per_each_inr IS NULL THEN \'Y\' ELSE \'N\' END AS cogs_fallback, CASE WHEN commission_pct IS NULL THEN \'Y\' ELSE \'N\' END AS commission_fallback, CASE WHEN cogs_per_each_inr IS NULL AND outbound_per_each_inr IS NULL THEN \'NO_COST_RATES\' WHEN budget_sku IS NULL THEN \'NO_BUDGET_LINE\' WHEN cogs_per_each_inr IS NOT NULL AND outbound_per_each_inr IS NOT NULL AND three_pl_storage_per_each_inr IS NOT NULL AND commission_pct IS NOT NULL THEN \'COMPLETE\' ELSE \'PARTIAL\' END AS cost_completeness FROM joined_budget );",
                    "transaction": true
